export default function build({ THREE, traits, ui, isGrabbed, assets }) {
  const root = new THREE.Group();

  const heart = assets.get('heart-bp3d');
  root.add(heart.object3D);
  heart.object3D.scale.setScalar(1.5);

  const steps = [
    {
      title: 'Step 1: Blood returns to the heart',
      text: 'Oxygen-poor blood from the body enters the right atrium through the superior and inferior venae cavae.',
      ids: ['superior_vena_cava', 'inferior_vena_cava', 'right_atrium'],
      hl: 'right_atrium',
      paths: [['superior_vena_cava', 'right_atrium'], ['inferior_vena_cava', 'right_atrium']],
      oxy: false,
    },
    {
      title: 'Step 2: Right atrium to right ventricle',
      text: 'The right atrium contracts and pushes blood through the tricuspid valve into the right ventricle.',
      ids: ['right_atrium', 'tricuspid_valve', 'right_ventricle'],
      hl: 'tricuspid_valve',
      paths: [['right_atrium', 'tricuspid_valve', 'right_ventricle']],
      oxy: false,
    },
    {
      title: 'Step 3: Out to the lungs',
      text: 'The right ventricle pumps blood through the pulmonary valve into the pulmonary trunk and the pulmonary arteries, toward the lungs.',
      ids: ['right_ventricle', 'pulmonary_valve', 'pulmonary_trunk', 'right_pulmonary_artery', 'left_pulmonary_artery'],
      hl: 'pulmonary_valve',
      paths: [
        ['right_ventricle', 'pulmonary_valve', 'pulmonary_trunk', 'right_pulmonary_artery'],
        ['pulmonary_valve', 'pulmonary_trunk', 'left_pulmonary_artery'],
      ],
      oxy: false,
    },
    {
      title: 'Step 4: Back from the lungs',
      text: 'In the lungs the blood picks up oxygen. Pulmonary veins carry this oxygen-rich blood into the left atrium.',
      ids: ['right_superior_pulmonary_vein', 'left_superior_pulmonary_vein', 'left_atrium'],
      hl: 'left_atrium',
      paths: [
        ['right_superior_pulmonary_vein', 'left_atrium'],
        ['left_superior_pulmonary_vein', 'left_atrium'],
      ],
      oxy: true,
    },
    {
      title: 'Step 5: Left atrium to left ventricle',
      text: 'Blood flows through the mitral valve into the left ventricle, the most muscular chamber.',
      ids: ['left_atrium', 'mitral_valve', 'left_ventricle'],
      hl: 'mitral_valve',
      paths: [['left_atrium', 'mitral_valve', 'left_ventricle']],
      oxy: true,
    },
    {
      title: 'Step 6: Out to the body',
      text: 'The left ventricle pumps blood through the aortic valve into the aorta, which delivers it to the whole body. Then the cycle repeats.',
      ids: ['left_ventricle', 'aortic_valve', 'ascending_aorta', 'arch_of_aorta'],
      hl: 'aortic_valve',
      paths: [['left_ventricle', 'aortic_valve', 'ascending_aorta', 'arch_of_aorta']],
      oxy: true,
    },
  ];

  const names = {
    superior_vena_cava: 'Superior vena cava',
    inferior_vena_cava: 'Inferior vena cava',
    right_atrium: 'Right atrium',
    tricuspid_valve: 'Tricuspid valve',
    right_ventricle: 'Right ventricle',
    pulmonary_valve: 'Pulmonary valve',
    pulmonary_trunk: 'Pulmonary trunk',
    right_pulmonary_artery: 'Right pulm. artery',
    left_pulmonary_artery: 'Left pulm. artery',
    right_superior_pulmonary_vein: 'Right pulm. vein',
    left_superior_pulmonary_vein: 'Left pulm. vein',
    left_atrium: 'Left atrium',
    mitral_valve: 'Mitral valve',
    left_ventricle: 'Left ventricle',
    aortic_valve: 'Aortic valve',
    ascending_aorta: 'Ascending aorta',
    arch_of_aorta: 'Aortic arch',
  };

  const labels = {};
  steps.forEach((s) => s.ids.forEach((id) => {
    if (!labels[id]) {
      labels[id] = heart.label(id, names[id]);
      labels[id].setVisible(false);
    }
  }));

  // Blood particles
  const particleMat = new THREE.MeshStandardMaterial({ color: 0x3b7bff, emissive: 0x1a4fd0, emissiveIntensity: 0.9 });
  const particleGeo = new THREE.SphereGeometry(0.008, 12, 8);
  const particles = [];
  for (let i = 0; i < 10; i++) {
    const m = new THREE.Mesh(particleGeo, particleMat);
    m.visible = false;
    m.name = 'BloodCell' + i;
    root.add(m);
    particles.push({ mesh: m, curve: null, phase: 0 });
  }

  let current = 0;
  let cut = false;
  let activeCurves = [];

  const panel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .count { color: #9aa3b2; font-size: 20px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
              border-radius: 12px; background-color: #3a404a; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
      .credit { color: #8d95a3; font-size: 18px; }
    </style>
    <div class="card">
      <span class="count" id="count">Step 1 of 6</span>
      <span class="title" id="title">Title</span>
      <span class="body" id="body">Body</span>
      <div class="row">
        <button class="btn2" id="back"><span class="bt">Back</span></button>
        <button class="btn" id="next"><span class="bt" id="nexttxt">Next</span></button>
        <button class="btn2" id="cut"><span class="bt" id="cuttxt">Cut open</span></button>
        <button class="btn2" id="restart"><span class="bt">Restart</span></button>
      </div>
      <span class="credit">Blue = oxygen-poor, red = oxygen-rich. ${heart.credit || 'Model: BodyParts3D, CC BY 4.0'}</span>
    </div>`, { width: 0.38, position: [0, 0.4, 0] });
  root.add(panel.object3D);

  function setStep(i) {
    current = Math.max(0, Math.min(steps.length - 1, i));
    const s = steps[current];
    panel.set('count', { text: 'Step ' + (current + 1) + ' of ' + steps.length });
    panel.set('title', { text: s.title });
    panel.set('body', { text: s.text });
    panel.set('nexttxt', { text: current === steps.length - 1 ? 'Done' : 'Next' });

    heart.xray(true, s.ids);
    heart.highlight(s.hl);
    heart.cutaway(cut);

    Object.keys(labels).forEach((id) => labels[id].setVisible(s.ids.indexOf(id) >= 0));

    // Build flow paths
    activeCurves = s.paths.map((p) => {
      const pts = p.map((id) => heart.anchor(id).clone());
      return new THREE.CatmullRomCurve3(pts);
    });
    particleMat.color.set(s.oxy ? 0xff3b3b : 0x3b7bff);
    particleMat.emissive.set(s.oxy ? 0xc01010 : 0x1a4fd0);
    const perCurve = Math.floor(particles.length / activeCurves.length);
    let k = 0;
    activeCurves.forEach((c) => {
      for (let j = 0; j < perCurve; j++) {
        const pr = particles[k++];
        pr.curve = c;
        pr.phase = j / perCurve;
        pr.mesh.visible = true;
      }
    });
    for (; k < particles.length; k++) {
      particles[k].curve = null;
      particles[k].mesh.visible = false;
    }
  }

  panel.on('next', 'click', () => setStep(current + 1));
  panel.on('back', 'click', () => setStep(current - 1));
  panel.on('cut', 'click', () => {
    cut = !cut;
    heart.cutaway(cut);
    panel.set('cuttxt', { text: cut ? 'Close' : 'Cut open' });
  });
  panel.on('restart', 'click', () => {
    heart.reset();
    cut = false;
    panel.set('cuttxt', { text: 'Cut open' });
    setStep(0);
  });

  setStep(0);

  return {
    root,
    update(time) {
      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        if (!p.curve) continue;
        const t = (time * 0.2 + p.phase) % 1;
        p.curve.getPoint(t, p.mesh.position);
      }
    },
  };
}
